#include <iostream>
#include <iomanip>
#include <array>
#include <algorithm>
#include <numeric>

constexpr size_t STUDENTS = 3;
constexpr size_t EXAMS = 4;

using GradeTable = std::array<std::array<int, EXAMS>, STUDENTS>;

int findMinimum(const GradeTable& grades) {
    int lowGrade = 100;
    for (const auto& studentGrades : grades) {
        for (int grade : studentGrades) {
            if (grade < lowGrade) {
                lowGrade = grade;
            }
        }
    }
    return lowGrade;
}

int findMaximum(const GradeTable& grades) {
    int highGrade = 0;
    for (const auto& studentGrades : grades) {
        for (int grade : studentGrades) {
            if (grade > highGrade) {
                highGrade = grade;
            }
        }
    }
    return highGrade;
}

double calculateAverage(const std::array<int, EXAMS>& setOfGrades) {
    int total = std::accumulate(setOfGrades.begin(), setOfGrades.end(), 0);
    return static_cast<double>(total) / setOfGrades.size();
}

void printTable(const GradeTable& grades) {
    std::cout << "                 [0]  [1]  [2]  [3]\n";
    for (size_t i = 0; i < grades.size(); ++i) {
        std::cout << "studentGrades[" << i << "] ";
        for (size_t j = 0; j < grades[i].size(); ++j) {
            std::cout << std::left << std::setw(5) << grades[i][j];
        }
        std::cout << "\n";
    }
}

int main() {
    GradeTable studentGrades = {{
        {77, 68, 86, 73},
        {96, 87, 89, 78},
        {70, 90, 86, 81}
    }};

    std::cout << "The array is:\n";
    printTable(studentGrades);

    std::cout << "\nLowest grade: " << findMinimum(studentGrades)
              << "\nHighest grade: " << findMaximum(studentGrades) << "\n";

    std::cout << std::fixed << std::setprecision(2);
    for (size_t student = 0; student < STUDENTS; ++student) {
        std::cout << "The average grade for student " << student 
                  << " is " << calculateAverage(studentGrades[student]) << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <iomanip>

// Passing dynamically sized 1D container in C++17
void print1DVector(const std::vector<int>& vec) {
    for (size_t i = 0; i < vec.size(); ++i) {
        std::cout << "array[" << i << "] = " << vec[i] << "\n";
    }
}

// Passing dynamically sized 2D container in C++17
void print2DVector(const std::vector<std::vector<int>>& matrix) {
    for (const auto& row : matrix) {
        for (int val : row) {
            std::cout << std::setw(5) << val;
        }
        std::cout << "\n";
    }
}

int main() {
    // Simulating runtime inputs
    size_t arraySize = 6;
    size_t row1 = 2, col1 = 5;
    size_t row2 = 4, col2 = 3;

    // 1D dynamically-sized container (modern replacement for 1D VLA)
    std::vector<int> array(arraySize);
    for (size_t i = 0; i < arraySize; ++i) {
        array[i] = static_cast<int>(i * i);
    }

    // 2D dynamic containers (modern replacement for 2D VLAs)
    std::vector<std::vector<int>> array2D1(row1, std::vector<int>(col1));
    for (size_t i = 0; i < row1; ++i) {
        for (size_t j = 0; j < col1; ++j) {
            array2D1[i][j] = static_cast<int>(i + j);
        }
    }

    std::vector<std::vector<int>> array2D2(row2, std::vector<int>(col2));
    for (size_t i = 0; i < row2; ++i) {
        for (size_t j = 0; j < col2; ++j) {
            array2D2[i][j] = static_cast<int>(i + j);
        }
    }

    std::cout << "One-dimensional array:\n";
    print1DVector(array);

    std::cout << "\nFirst two-dimensional array:\n";
    print2DVector(array2D1);

    std::cout << "\nSecond two-dimensional array:\n";
    print2DVector(array2D2);

    return 0;
}
